/* =========================================================
   ELEMENTOR HTML WIDGET RUNTIME FIX
   The full-page background is moved to document.body by JS.
   These rules override page/template/container backgrounds,
   including Elementor background overlays and pseudo layers.
   ========================================================= */
html.dgs-webdev-active,
html.dgs-webdev-active body.dgs-webdev-active{
  background:#050508 !important;
  background-color:#050508 !important;
  background-image:none !important;
  min-height:100% !important;
}

body.dgs-webdev-active::before,
body.dgs-webdev-active::after{
  background:transparent !important;
  background-color:transparent !important;
  background-image:none !important;
  opacity:0 !important;
  pointer-events:none !important;
}

body.dgs-webdev-active #dgs-global-bg-root{
  position:fixed !important;
  inset:0 !important;
  width:100vw !important;
  height:100vh !important;
  z-index:0 !important;
  display:block !important;
  visibility:visible !important;
  opacity:1 !important;
  overflow:hidden !important;
  pointer-events:none !important;
  background-color:#050508 !important;
  background-image:
    radial-gradient(circle at 14% 18%,rgba(167,139,250,.9) 0 1px,transparent 1.7px),
    radial-gradient(circle at 72% 22%,rgba(49,231,255,.75) 0 1px,transparent 1.8px),
    radial-gradient(circle at 38% 74%,rgba(255,77,160,.7) 0 1px,transparent 1.7px),
    radial-gradient(circle at 86% 66%,rgba(255,255,255,.75) 0 1px,transparent 1.6px),
    #050508 !important;
  background-size:210px 210px,280px 280px,340px 340px,430px 430px,auto !important;
  isolation:isolate !important;
}

body.dgs-webdev-active #dgs-global-bg-root #globalStarfield{
  position:absolute !important;
  inset:0 !important;
  width:100% !important;
  height:100% !important;
  z-index:0 !important;
  display:block !important;
  visibility:visible !important;
  opacity:.98 !important;
  background:transparent !important;
}

body.dgs-webdev-active #dgs-global-bg-root .global-mesh{
  position:absolute !important;
  inset:0 !important;
  z-index:1 !important;
  background:transparent !important;
}

body.dgs-webdev-active #dgs-global-bg-root .noise{
  position:absolute !important;
  inset:0 !important;
  z-index:2 !important;
  background-color:transparent !important;
}

